-- v3f08_sampling_approximation / ex3 — deterministic, join-stable hash sampling.
SELECT count(*) FILTER (
           WHERE ('x' || substr(md5(id::text), 1, 8))::bit(32)::int % 100 = 0
       ) AS sampled_customers,
       count(*) FILTER (
           WHERE ('x' || substr(md5(id::text), 1, 8))::bit(32)::int % 100 = 0
       ) * 100 AS est_total_customers,
       count(*) AS actual_customers
FROM customers;
